"use client"

import React, { useRef } from "react"
import { useIntersection } from "react-use"
import { useTranslations } from "next-intl"
import { useEnrollStatus } from "@/queries/enroll-status"
import type { Course } from "@/schema/course"
import { cn } from "@/utils/cn"

type CourseStatusProps = {
  course: Course
}

export function CourseStatus({ course }: CourseStatusProps) {
  const t = useTranslations("course-detail.enroll-status")
  const intersectionRef = useRef<HTMLDivElement>(null)
  const intersection = useIntersection(
    intersectionRef as React.RefObject<HTMLDivElement>,
    {
      root: null,
      rootMargin: "0px",
      threshold: 1,
    }
  )
  const { data, isLoading } = useEnrollStatus(
    course,
    (intersection?.intersectionRatio ?? 0) > 0
  )

  return (
    <div ref={intersectionRef} className="flex gap-3 text-xs leading-[1.15rem]">
      <CourseStatusItem
        label={t("enrolled")}
        count={data?.enrolled}
        total={course.studentQuota.total - course.studentQuota.nonNtu}
        isLoading={isLoading}
      />
      <CourseStatusItem
        label={t("other-dept")}
        count={data?.enrolledOtherDept}
        total={course.studentQuota.otherDepts}
        isLoading={isLoading}
      />
      <CourseStatusItem
        label={t("remaining")}
        count={data?.remaining}
        isLoading={isLoading}
      />
      <CourseStatusItem
        label={t("registered")}
        count={data?.registered}
        isLoading={isLoading}
      />
    </div>
  )
}

type CourseStatusItemProps = {
  label: string
  count?: number
  total?: number
  isLoading: boolean
}

function CourseStatusItem(props: CourseStatusItemProps) {
  return (
    <div className="min-w-12">
      {props.label}
      <div className="flex items-baseline gap-px">
        <span
          className={cn(
            "text-sm font-semibold text-black transition-colors",
            props.isLoading && "text-black/40"
          )}
        >
          {props.count ?? 0}
        </span>
        {props.total !== undefined && (
          <>
            <span>/</span>
            <span>{props.total}</span>
          </>
        )}
      </div>
    </div>
  )
}

import { useQuery } from "@tanstack/react-query"
import { useProgress } from "@/queries/progress"
import { queryKeys } from "@/lib/query-keys"
import type { PreselectCourse, Course } from "@/schema/course"
import { CourseStatus } from "@/schema/course"
import { Status } from "@/types/phase"
import axiosInstance from "@/utils/axios"

export type EnrollStatus = {
  enrolled: number
  enrolledOtherDept: number
  registered: number
  remaining: number
}

export const useEnrollStatus = (
  course: PreselectCourse | Course,
  enabled = false
) => {
  const { data } = useProgress()
  const isNotSelecting =
    course.status === CourseStatus.Canceled ||
    !data?.progress ||
    (data.progress.phase === "PreReg1" &&
      data.progress.status === Status.Preselecting)
  const isCurrentSemester = data?.semester === course.semester

  const query = useQuery<EnrollStatus>({
    queryKey: queryKeys.enrollStatus(course.id),
    queryFn: async () => {
      if (isNotSelecting)
        return {
          enrolled: 0,
          enrolledOtherDept: 0,
          registered: 0,
          remaining: course.studentQuota.total - course.studentQuota.nonNtu,
        }
      const res = await axiosInstance.get(
        `/v1/courses/enroll-status/${course.id}`
      )
      return res.data
    },
    retry: false,
    enabled: enabled && isCurrentSemester,
    staleTime: 5 * 60 * 1000, // 5 minutes
  })

  return query
}

import { z } from "zod"

export enum Phase {
  PreReg1 = "prereg1",
  PreReg2 = "prereg2",
  AddDrop1 = "adddrop1",
  AddDrop2 = "adddrop2",
  AddDrop3 = "adddrop3",
  AddDrop4 = "adddrop4",
  Final = "final",
}

export const phases = { ...Phase }

export const urlToPhaseMapping = Object.fromEntries(
  Object.entries(Phase).map(([key, value]) => [value, key])
) as Record<Phase, keyof typeof Phase>

export enum View {
  Priority = "priority",
  Result = "result",
}

export enum ViewType {
  List = "list",
  Table = "table",
}

export enum Status {
  Preselecting = "Preselecting",
  Started = "Started",
  Waiting = "Waiting",
  Ended = "Ended",
}

const Progress = z.object({
  canAddCourse: z.boolean(),
  endAt: z.string(),
  link: z.string(),
  phase: z.enum(Object.keys(Phase) as [keyof typeof Phase]),
  status: z.nativeEnum(Status),
  startAt: z.string(),
})

type Progress = z.infer<typeof Progress>

const RawProgresses = z.object({
  progress: Progress.nullable(),
  progresses: Progress.array(),
  semester: z.string(),
  semesterList: z.string().array(),
})

export const Progresses = RawProgresses.transform((raw) => ({
  progress: raw.progress,
  progresses: raw.progresses,
  semester: raw.semester,
  semesterList: raw.semesterList
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }))
    .reverse()
    .map((semester) => ({
      semester,
      year: parseInt(semester.split("-")[0]),
      term: parseInt(semester.split("-")[1]),
    })),
  current: raw.progress?.phase ? phases[raw.progress.phase] : null,
}))

export type Progresses = z.infer<typeof Progresses>

