"use client"

import { useTranslations } from "next-intl"
import { useEnrollStatus, type EnrollStatus } from "@/queries/enroll-status"
import { useProgress } from "@/queries/progress"
import type { Course } from "@/schema/course"
import { cn } from "@/utils/cn"

interface EnrollStatusProps {
  course: Course
}

export default function EnrollStatus({ course }: EnrollStatusProps) {
  const t = useTranslations("course-detail.enroll-status")
  const { data: progress } = useProgress()
  const { data, isLoading } = useEnrollStatus(course, true)

  const showOtherDept =
    !progress?.progress || // 資料還沒載完時
    progress.progress.phase === "PreReg1" ||
    progress.progress.phase === "PreReg2"

  return (
    <div className="flex w-fit gap-6 py-1.5 text-right md:w-fit">
      <EnrollStatusItem
        label={t("enrolled")}
        count={data?.enrolled}
        total={course.studentQuota.total - course.studentQuota.nonNtu}
        isLoading={isLoading}
      />
      {showOtherDept && (
        <EnrollStatusItem
          label={t("other-dept")}
          count={data?.enrolledOtherDept}
          total={course.studentQuota.otherDepts}
          isLoading={isLoading}
        />
      )}
      <EnrollStatusItem
        label={t("remaining")}
        count={data?.remaining}
        isLoading={isLoading}
      />
      <EnrollStatusItem
        label={t("registered")}
        count={data?.registered}
        isLoading={isLoading}
      />
    </div>
  )
}

type EnrollStatusItemProps = {
  label: string
  count?: number
  total?: number
  isLoading: boolean
}

function EnrollStatusItem(props: EnrollStatusItemProps) {
  return (
    <div className="flex w-fit flex-col gap-1 md:min-w-20">
      <span className="text-sm whitespace-pre text-gray-500">
        {props.label}
      </span>
      <div className="flex items-baseline justify-end gap-0.5">
        <span
          className={cn(
            "text-2xl font-bold",
            props.isLoading && "text-black/40"
          )}
        >
          {props.count ?? 0}
        </span>
        {props.total !== undefined && (
          <>
            <span className="text-sm">/</span>
            <span className="text-sm">{props.total}</span>
          </>
        )}
      </div>
    </div>
  )
}

import { useQuery } from "@tanstack/react-query"
import { queryKeys } from "@/lib/query-keys"
import { Progresses } from "@/types/phase"
import axiosInstance from "@/utils/axios"

export const useProgress = () => {
  const query = useQuery({
    queryKey: queryKeys.progress,
    queryFn: async () => {
      const res = await axiosInstance.get<Progresses>("/v3/config/progresses")
      return Progresses.parse(res.data)
    },
    staleTime: 1000 * 60 * 60 * 24, // 24 hours
  })

  return query
}

