import { Children, type PropsWithChildren } from "react"
import { getTranslations } from "next-intl/server"
import { cookies } from "next/headers"
import { ArrowRightIcon } from "lucide-react"
import { menus } from "@/components/header/menu/menus"
import { Button } from "@/components/ui/button"
import { Locale, Link as NextLink } from "@/i18n/routing"
import { hrefMap } from "@/lib/href"
import { SearchType } from "@/types/filter"
import { Phase, Status, ViewType } from "@/types/phase"
import PhaseStep from "./phase-step"

interface SearchTypeParams {
  params: Promise<{ locale: Locale }>
}

export default async function HomePage(props: SearchTypeParams) {
  const params = await props.params
  const it = await getTranslations("header.menus.info.acquaintance")

  // temp translation
  function t(zh: string, en: string) {
    return params.locale === Locale.zhTW ? zh : en
  }

  // temp translation
  function w(weekday: number) {
    return {
      0: t("日", "Sun"),
      1: t("一", "Mon"),
      2: t("二", "Tue"),
      3: t("三", "Wed"),
      4: t("四", "Thu"),
      5: t("五", "Fri"),
      6: t("六", "Sat"),
    }[weekday] as string
  }

  const cookieStore = await cookies()
  const isLoggedIn = !!cookieStore.get("auth")

  // 選課流程資料 —— 每學期改這裡就好。日期是「顯示用」字串(刻意手寫,例如選課寫到
  // 1.21 但技術上到次日凌晨 03:00),不從 API 拿;API(useProgress)只用來判斷哪一格
  // 進行中(phase + status 對到 progress 就亮 + shimmer)。有 phase/status 的格子才會亮。
  const phases: PhaseData[] = [
    {
      number: "01",
      color: "#2563eb",
      title: t("初選一階", "Pre-selection I"),
      start: `08.19 (${w(3)})`,
      end: `08.21 (${w(5)})`,
      steps: [
        {
          phase: Phase.PreReg1,
          status: Status.Preselecting,
          href: hrefMap.priority(ViewType.List),
          dateLabel: `8.3 (${w(1)}) ~ 8.18 (${w(2)})`,
          label: t("預選", "Pre-selection"),
          activeLabel: t("預選中", "Preselecting"),
        },
        {
          phase: Phase.PreReg1,
          status: Status.Started,
          href: "https://if177.aca.ntu.edu.tw",
          external: true,
          dateLabel: `8.19 (${w(3)}) ~ 8.21 (${w(5)})`,
          subLabel: t(
            "每天上午 09:00 - 次日凌晨 03:00",
            "09:00 AM – 03:00 AM next day"
          ),
          label: t("選課", "Selection"),
          activeLabel: t("選課中", "Selecting"),
        },
        // 分發 = 等結果:靠 Waiting 狀態驅動高亮
        {
          phase: Phase.PreReg1,
          status: Status.Waiting,
          dateLabel: `8.22 (${w(6)}) ~ 8.24 (${w(1)})`,
          label: t("分發", "Allocation"),
          activeLabel: t("分發中", "Allocating"),
        },
        // 一階無 Ended:Waiting 完直接跳 PreReg2/Preselecting,故公布結果掛該狀態,
        // 與初選二階「預選」同一時窗 —— 該時窗兩格會一起亮,屬預期。
        {
          phase: Phase.PreReg2,
          status: Status.Preselecting,
          href: hrefMap.result(Phase.PreReg1, ViewType.List),
          dateLabel: `8.24 (${w(1)}) 15:00`,
          label: t("公布結果", "Results"),
          activeLabel: t("公布結果中", "Announcing"),
        },
      ],
    },
    {
      number: "02",
      color: "#ea580c",
      title: t("初選二階", "Pre-selection II"),
      start: `08.25 (${w(2)})`,
      end: `08.26 (${w(3)})`,
      steps: [
        // 開放預選:靠 Preselecting 狀態驅動高亮
        {
          phase: Phase.PreReg2,
          status: Status.Preselecting,
          href: hrefMap.priority(ViewType.List),
          dateLabel: `8.24 (${w(1)})`,
          label: t("預選", "Pre-selection"),
          activeLabel: t("預選中", "Preselecting"),
        },
        {
          phase: Phase.PreReg2,
          status: Status.Started,
          href: "https://if177.aca.ntu.edu.tw",
          external: true,
          dateLabel: `8.25 (${w(2)}) ~ 8.26 (${w(3)})`,
          subLabel: t(
            "每天上午 09:00 - 次日凌晨 03:00",
            "09:00 AM – 03:00 AM next day"
          ),
          label: t("選課", "Selection"),
          activeLabel: t("選課中", "Selecting"),
        },
        {
