"use client"

import { Fragment, useCallback, useEffect, useRef, useState } from "react"
import { useTranslations } from "next-intl"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { useRouter } from "@/i18n/routing"
import { hrefMap } from "@/lib/href"
import { useEnrollStatus } from "@/queries/enroll-status"
import type { Course } from "@/schema/course"
import type { Schedule } from "@/schema/schedule"
import { cn } from "@/utils/cn"
import { GRID_TEMPLATE } from "./priority-grid"

/**
 * 志願序列表所有列的外殼:套 grid 欄寬、共用 hover / border 樣式、點列導頁。
 * 各列只負責填三段內容(志願序欄、RowInfoCells、動作欄);差異用 className 覆寫。
 */
export function PriorityRowShell({
  course,
  refCb,
  navigable = true,
  className,
  children,
}: {
  course: Course
  /** 掛在列元素上的 ref(如 dnd sortable + 進場觀察合併後的 ref)。 */
  refCb?: (node: HTMLDivElement | null) => void
  /** 可否點列進課程頁(編輯中的志願序列不可)。 */
  navigable?: boolean
  className?: string
  children: React.ReactNode
}) {
  const router = useRouter()
  return (
    <div
      ref={refCb}
      onClick={(e) => {
        if (!navigable) return
        if ((e.target as HTMLElement).closest("button, a, input")) return
        router.push(hrefMap.course(course.semester, course.serial))
      }}
      style={{ gridTemplateColumns: GRID_TEMPLATE }}
      className={cn(
        "group -mt-px grid min-h-11 items-center border-y bg-white transition-colors duration-0 hover:z-10 hover:bg-gray-100 hover:shadow-sm",
        className
      )}
    >
      {children}
    </div>
  )
}

/** 進入視窗才抓「已選 / 登記人數」。回傳 observe(掛在列元素上)與結果。 */
export function useRowEnrollStatus(course: Course) {
  const [isVisible, setIsVisible] = useState(false)
  const elRef = useRef<HTMLElement | null>(null)

  const observe = useCallback((node: HTMLElement | null) => {
    elRef.current = node
  }, [])

  useEffect(() => {
    const el = elRef.current
    if (!el) return
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) setIsVisible(true)
      },
      { threshold: 0 }
    )
    observer.observe(el)
    return () => observer.disconnect()
  }, [])

  const { data: enrollStatus, isLoading } = useEnrollStatus(course, isVisible)
  return { observe, enrollStatus, enrollLoading: isLoading, isVisible }
}

type EnrollStatus = ReturnType<typeof useRowEnrollStatus>["enrollStatus"]

/**
 * 中間共用欄位(流水號 → 登記人數,共 8 欄),已選上 / 已登記 / 待登記三種列共用。
 * 回傳 fragment,直接當作 grid row 的子元素。
 */
export function RowInfoCells({
  course,
  enrollStatus,
  enrollLoading,
  isVisible,
  nameSuffix,
  failReason,
  linkable = true,
}: {
  course: Course
  enrollStatus: EnrollStatus
  enrollLoading: boolean
  isVisible: boolean
  /** 課名後的內容(如加退選的加選方式標籤,可用 ml-auto 推到欄位右緣)。 */
  nameSuffix?: React.ReactNode
  /** 上次送出時的登記失敗原因,顯示在課名下方。 */
  failReason?: string
  /** 整列是否可點進課程頁 —— 編輯模式的志願序列不是連結,課名 hover 不加底線。 */
  linkable?: boolean
}) {
  const tw = useTranslations("schedule.table")
  const ts = useTranslations("course-detail.schedule")
  // enter 動畫只在人數「第一次出現」時跑一次。之後不再跑 —— 否則拖曳時列的 DOM 被
  // 反覆搬動會一直重播 fade-in,drop 時也會再閃一兩下。
  const hasAnimatedRef = useRef(false)

  // 每個時段拆成 { 時間, 地點 },inline 顯示接成一行(過長會 truncate),
  // tooltip 用 grid 一排一排列出完整的時間與教室。
  const scheduleRows = course.schedules.map((s: Schedule) => {
    const day = tw("weekday", { day: s.weekday - 1 })
    const intervals = s.intervals.map((x) => (x === "X" ? "10" : x)).join(",")
    return {
      time: `${day} ${intervals}`,
      location: s.classroom?.name ?? ts("no-location"),
    }
  })
  const time = scheduleRows.map((r) => r.time).join(" / ")

  const ntuLimit = course.studentQuota.total - course.studentQuota.nonNtu
  const showCount = !enrollLoading && isVisible && enrollStatus
  const animate = !!showCount && !hasAnimatedRef.current
  useEffect(() => {
    if (showCount) hasAnimatedRef.current = true
  }, [showCount])
  const countCn = animate
    ? "inline-block animate-in duration-300 fade-in slide-in-from-bottom-2"
    : "inline-block"

  return (
    <>
      <div className="px-2 text-left">{course.serial}</div>
      <div className="min-w-0 px-2 py-1.5 text-left">
        <div className="flex items-center gap-1.5">
          <span
            className={cn(
              "line-clamp-2 w-fit text-balance",
              linkable && "group-hover:underline"
            )}
          >
            {course.name}
          </span>
          {nameSuffix}
        </div>
        {failReason && (
          <p className="mt-0.5 text-xs leading-tight text-error-main">
            {failReason}
          </p>
        )}
      </div>
      <div className="min-w-0 truncate px-2 text-left">
        {course.teacher.name}
      </div>
      <div className="px-2 text-right">{course.credits}</div>
      {scheduleRows.length > 0 ? (
        <div className="min-w-0 px-2 text-left">
          {/* trigger 只包時間文字(w-fit),tooltip 才會對齊文字而不是整個 cell */}
          {/* disableHoverableContent:tooltip 內容不可 hover,游標離開時間文字就收起。 */}
          <Tooltip disableHoverableContent>
            <TooltipTrigger asChild>
              <span className="block w-fit max-w-full truncate tabular-nums">
                {time}
              </span>
            </TooltipTrigger>
            {/* trigger 是 w-fit 的時間文字,align 用預設 center → tooltip 置中對齊
                時間文字本身(文字不一定填滿 cell,故不能對齊 cell)。 */}
            <TooltipContent side="top">
              <div className="grid grid-cols-[auto_auto] gap-x-4 gap-y-1">
                {scheduleRows.map((r, i) => (
                  <Fragment key={i}>
                    <span className="whitespace-nowrap tabular-nums">
                      {r.time}
                    </span>
                    <span className="text-right text-popover/70">
                      {r.location}
                    </span>
                  </Fragment>
                ))}
              </div>
            </TooltipContent>
          </Tooltip>
        </div>
      ) : (
        <div className="min-w-0 truncate px-2 text-left">{time}</div>
      )}
      <div className="px-2 text-right">{ntuLimit}</div>
      <div className="px-2 text-right">
        {showCount && <span className={countCn}>{enrollStatus.enrolled}</span>}
      </div>
      <div className="px-2 text-right">
        {showCount && (
          <span className={countCn}>{enrollStatus.registered}</span>
        )}
      </div>
    </>
  )
}

// 志願序列表的共用 grid 欄位模板 —— header 與每一列都套用同一組欄寬,
// 以 CSS grid 取代 <table>,讓區塊可以有 min-height、拖曳可用原生 sortable。
// 每列各自是一個 grid(非 subgrid),欄寬必須是固定值 / fr 才能跨列對齊,不能用
// auto / fit-content —— 否則表頭那格(文字)與資料列那格(數字 / 內容)會各自算出
// 不同寬度而錯位。
// 首欄剛好放得下「志願序」表頭:3 個全形字 @ text-sm(0.875rem)+ px-2(1rem)= 3.625rem。
// 只有課名彈性(minmax…1fr):吸收整列剩餘空間,讓操作欄維持靠右;老師 / 時間 用固定
// 的內容寬(fr 是照空間比例、不是內容,三欄都 fr 會各撐一片空白);其餘欄位壓到剛好容納
// 表頭的固定寬度(固定值為估值,實際請在畫面上微調)。
// 欄位:志願序 流水號 課名 老師 學分 時間 本校上限 已選 登記 操作
export const GRID_TEMPLATE =
  "3.625rem 4rem minmax(9rem,1fr) 5.5rem 3rem 11rem 4.5rem 4.5rem 4.5rem 7rem"

// 已登記區塊至少維持 4 列高度(沒課 / 課少時撐開,和空狀態一致)。
export const ORDERED_MIN_ROWS = 4
export const ROW_HEIGHT_REM = 2.75

