import { useQuery } from "@tanstack/react-query"
import { useProgress } from "@/queries/progress"
import { queryKeys } from "@/lib/query-keys"
import type { PreselectCourse, Course } from "@/schema/course"
import { CourseStatus } from "@/schema/course"
import { Status } from "@/types/phase"
import axiosInstance from "@/utils/axios"

export type EnrollStatus = {
  enrolled: number
  enrolledOtherDept: number
  registered: number
  remaining: number
}

export const useEnrollStatus = (
  course: PreselectCourse | Course,
  enabled = false
) => {
  const { data } = useProgress()
  const isNotSelecting =
    course.status === CourseStatus.Canceled ||
    !data?.progress ||
    (data.progress.phase === "PreReg1" &&
      data.progress.status === Status.Preselecting)
  const isCurrentSemester = data?.semester === course.semester
  // 初選登記中(選課 / 分發皆尚未公布結果):只有「已登記」有意義,已選上 / 外系已選上 /
  // 剩餘名額都要等結果公布才準,故在此期間不顯示這三項。
  const isRegistering =
    !!data?.progress &&
    (data.progress.phase === "PreReg1" || data.progress.phase === "PreReg2") &&
    (data.progress.status === Status.Started ||
      data.progress.status === Status.Waiting)

  const query = useQuery<EnrollStatus>({
    queryKey: queryKeys.enrollStatus(course.id),
    queryFn: async () => {
      if (isNotSelecting)
        return {
          enrolled: 0,
          enrolledOtherDept: 0,
          registered: 0,
          remaining: course.studentQuota.total - course.studentQuota.nonNtu,
        }
      const res = await axiosInstance.get(
        `/v1/courses/enroll-status/${course.id}`
      )
      return res.data
    },
    retry: false,
    enabled: enabled && isCurrentSemester,
    staleTime: 5 * 60 * 1000, // 5 minutes
  })

  return { ...query, isRegistering }
}

